/* Glass sidebar. A thin light edge replaces a blur, because a blur redraws under motion. */
[data-slot="sidebar-inner"] { background: rgba(13, 21, 38, 0.84) !important; border-right: 1px solid rgba(246, 241, 233, 0.09) !important; }
/* A fading amethyst to teal hairline under the chat header. */
[data-chat-header] { border-bottom: 1px solid transparent; border-image: linear-gradient(90deg, transparent, #583090, #20969c, transparent) 1; }
/* Soft glass cards and popups with a light edge. */
[data-thread-details-card], [data-slot="popover-popup"], [data-slot="menu-popup"], [data-slot="dialog-popup"] { background: rgba(21, 32, 58, 0.94) !important; border: 1px solid rgba(246, 241, 233, 0.12) !important; border-radius: 14px !important; }
/* The composer is a glass pill. The lantern glow lights it when it has focus. */
[data-slot="composer-host"] { border-radius: 20px !important; border: 1px solid rgba(246, 241, 233, 0.12) !important; background: rgba(16, 25, 48, 0.82) !important; }
[data-slot="composer-host"]:focus-within { border-color: rgba(251, 177, 60, 0.5) !important; box-shadow: 0 0 0 1px rgba(251, 177, 60, 0.35), 0 0 30px -8px rgba(251, 177, 60, 0.55) !important; }
/* The user bubble gets round corners and an amethyst edge. */
[data-user-message-bubble] { border-radius: 18px !important; border: 1px solid rgba(163, 131, 227, 0.28) !important; }
.chat-markdown-codeblock { border: 1px solid rgba(246, 241, 233, 0.1) !important; border-radius: 12px !important; }
[data-thread-item] { border-radius: 10px !important; }
/* A thread with a working agent gets a faint amethyst tint. */
[data-thread-item]:has([aria-label*=", Working"]) { background: rgba(163, 131, 227, 0.12) !important; }
[data-slot="project-monogram"] { border-radius: 50% !important; }
::-webkit-scrollbar-thumb { background: #26345a; border-radius: 8px; }
::-webkit-scrollbar-thumb:hover { background: #8a93ad; }
[data-slot="scroll-area-thumb"] { background: #26345a !important; border-radius: 8px !important; }
/* The usage card shows the percent that remains, so the value says so. */
[data-thread-details-card] [aria-label$="% left"] > span:last-child::after { content: " left"; font-weight: 400; color: #b3a998; }
/* A thicker bar on a quiet track makes the level easy to read. */
[data-thread-details-card] [aria-label$="% left"] > span:nth-child(2), [data-thread-details-card] [aria-label^="Context:"] > span:nth-child(2) { height: 5px; background: #1d2a4a !important; }
/* The limit bar takes the look gradient. The warning and error colours of the app stay. */
[data-thread-details-card] [aria-label$="% left"] > span:nth-child(2) > span:first-child:not([class*="bg-warning"]):not([class*="bg-error"]) { background: linear-gradient(90deg, #7e52c4, #20969c) !important; }
[data-thread-details-card] [aria-label^="Context:"] > span:nth-child(2) > span:first-child:not([class*="bg-warning"]):not([class*="bg-error"]) { background: linear-gradient(90deg, #20969c, #1a8a6a) !important; }
/* The reply container. A pane of night glass holds the reply, so both sides of the talk have a frame. */
[data-message-role="assistant"] .chat-markdown { background: rgba(13, 20, 38, 0.66) !important; border: 1px solid rgba(160, 180, 230, 0.16); border-left: 2px solid rgba(32, 150, 156, 0.6); border-radius: 12px; padding: 14px 16px; }
[data-message-role="assistant"] .chat-markdown > :first-child { margin-top: 0 !important; }
[data-message-role="assistant"] .chat-markdown > :last-child { margin-bottom: 0 !important; }
[data-timeline-row-kind="work"] .chat-markdown { background: none !important; border: 0 !important; padding: 0 !important; }
